beforeExample:
public class TestClass {
    class OuterClass {
        static enum InnerEnum {
            CONSTANT1,
            CONSTANT2;
            void doSomething() { }
        }
    }

    interface OuterInterface {
        static enum InnerInterfaceEnum {
            CONSTANT_A,
            CONSTANT_B;
            int value;
            InnerInterfaceEnum() { this.value = 0; }
        }
    }
}

afterExample:
public class TestClass {
    class OuterClass {
        enum InnerEnum {
            CONSTANT1,
            CONSTANT2;
            void doSomething() { }
        }
    }

    interface OuterInterface {
        enum InnerInterfaceEnum {
            CONSTANT_A,
            CONSTANT_B;
            int value;
            InnerInterfaceEnum() { this.value = 0; }
        }
    }
}

negativeExample:
// Top-level enum, should not match
enum TopLevelEnum {
    VAL1, VAL2;
    void someMethod() {}
}

// Class with static modifier (illegal in top-level context, but not matched by enum rule if legal)
class ContainingClass {
    static class StaticInnerClass { /* legal for nested class */ }
}

// Enum field, not an enum declaration
class HasEnumField {
    enum MyEnum { V1 };
    private static MyEnum field = MyEnum.V1; // should not match
}
